void Halfedge_Mesh::set_corner_normals(float threshold) {

	//should the faces on either side of an edge be smoothed together?
	auto smooth_across = [&](EdgeRef e) -> bool {
		if (e->on_boundary()) return false; //smoothing never crosses the boundary
		if (threshold < 0.0f) return true; //negative threshold: everything is smooth
		if (e->sharp) return false; //explicitly sharp edges are always sharp
		if (threshold > 180.0f) return false; //threshold beyond 180: everything is sharp
		float cos_angle = dot(e->halfedge->face->normal(), e->halfedge->twin->face->normal());
		cos_angle = std::max(-1.0f, std::min(1.0f, cos_angle));
		return Degrees(std::acos(cos_angle)) <= threshold;
	};

	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) continue;
		HalfedgeRef h = f->halfedge;
		do {
			//sum the normals of every face in the smoothing group at this corner:
			Vec3 normal = Vec3(0.0f, 0.0f, 0.0f);

			//walk counter-clockwise around the vertex, starting at h's face:
			HalfedgeRef h2 = h;
			bool wrapped = false;
			while (true) {
				normal += h2->face->normal();
				if (!smooth_across(h2->edge)) break; //next face is not in the group
				h2 = h2->twin->next;
				if (h2 == h) { //went all the way around the vertex
					wrapped = true;
					break;
				}
			}

			//walk clockwise around the vertex, starting at h's face:
			if (!wrapped) {
				h2 = h;
				while (true) {
					//find the halfedge before h2 in its face loop:
					HalfedgeRef p = h2->next;
					while (p->next != h2) p = p->next;
					//crossing p's edge leads to the previous face around the vertex:
					if (!smooth_across(p->edge)) break;
					h2 = p->twin;
					if (h2 == h) break; //already counted (paranoia; implies wrapped)
					normal += h2->face->normal();
				}
			}

			h->corner_normal = normal.unit();
			h = h->next;
		} while (h != f->halfedge);
	}
}

void Halfedge_Mesh::set_corner_uvs_per_face() {
	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) continue;

		Vec3 n = f->normal();
		Vec3 c = f->center();

		//build a tangent frame on the plane perpendicular to the face normal,
		//starting from the direction of the face's first edge:
		Vec3 d = f->halfedge->twin->vertex->position - f->halfedge->vertex->position;
		Vec3 u = d - n * dot(d, n);
		if (u.norm_squared() == 0.0f) {
			//degenerate face; nothing sensible to project:
			HalfedgeRef h = f->halfedge;
			do {
				h->corner_uv = Vec2(0.0f, 0.0f);
				h = h->next;
			} while (h != f->halfedge);
			continue;
		}
		u = u.unit();
		Vec3 v = cross(n, u);

		//project each vertex of the face onto the tangent plane:
		HalfedgeRef h = f->halfedge;
		do {
			Vec3 p = h->vertex->position - c;
			h->corner_uv = Vec2(dot(p, u), dot(p, v));
			h = h->next;
		} while (h != f->halfedge);
	}
}

