// Sanity checks for flip_orientation, set_corner_normals, set_corner_uvs_per_face.
#include "geometry/halfedge.h"

#include <cmath>
#include <cstdio>
#include <string>

static int failures = 0;

static void check(bool ok, std::string const &msg) {
	if (!ok) {
		++failures;
		printf("FAIL: %s\n", msg.c_str());
	} else {
		printf("ok: %s\n", msg.c_str());
	}
}

static bool close(Vec3 a, Vec3 b, float eps = 1e-4f) {
	return (a - b).norm() < eps;
}

static Halfedge_Mesh cube_mesh() {
	return Halfedge_Mesh::from_indexed_faces({
		Vec3(-1,-1,-1), Vec3( 1,-1,-1), Vec3( 1, 1,-1), Vec3(-1, 1,-1),
		Vec3(-1,-1, 1), Vec3( 1,-1, 1), Vec3( 1, 1, 1), Vec3(-1, 1, 1)
	}, {
		{0, 3, 2, 1}, // -z
		{4, 5, 6, 7}, // +z
		{0, 1, 5, 4}, // -y
		{2, 3, 7, 6}, // +y
		{0, 4, 7, 3}, // -x
		{1, 2, 6, 5}, // +x
	});
}

static void test_flip_orientation() {
	{ //flip twice returns to original orientation; mesh stays valid
		Halfedge_Mesh mesh = cube_mesh();
		std::vector<Vec3> before;
		for (auto const &f : mesh.faces) before.emplace_back(f.normal());
		mesh.flip_orientation();
		check(!mesh.validate(), "flip_orientation: cube remains valid after one flip");
		std::vector<Vec3> mid;
		for (auto const &f : mesh.faces) mid.emplace_back(f.normal());
		bool flipped = true;
		for (size_t i = 0; i < before.size(); ++i) flipped = flipped && close(mid[i], -before[i]);
		check(flipped, "flip_orientation: face normals are negated");
		mesh.flip_orientation();
		check(!mesh.validate(), "flip_orientation: cube remains valid after two flips");
		bool restored = true;
		auto it = mesh.faces.begin();
		for (size_t i = 0; i < before.size(); ++i, ++it) restored = restored && close(it->normal(), before[i]);
		check(restored, "flip_orientation: flipping twice restores orientation");
	}
	{ //mesh with boundary stays valid
		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces({
			Vec3(0,0,0), Vec3(1,0,0), Vec3(2,0,0),
			Vec3(0,0,1), Vec3(1,0,1), Vec3(2,0,1)
		}, {
			{0, 3, 4, 1},
			{1, 4, 5, 2}
		});
		mesh.flip_orientation();
		check(!mesh.validate(), "flip_orientation: mesh with boundary remains valid");
		//both faces should now wind the other way (normal negated):
		for (auto const &f : mesh.faces) {
			if (f.boundary) continue;
			check(close(f.normal(), Vec3(0,-1,0)), "flip_orientation: boundary mesh normal negated");
		}
	}
}

static void test_corner_normals() {
	{ //cube with threshold 30 degrees: all edges sharp, corner normal == face normal
		Halfedge_Mesh mesh = cube_mesh();
		mesh.set_corner_normals(30.0f);
		bool ok = true;
		for (auto const &h : mesh.halfedges) {
			if (h.face->boundary) continue;
			ok = ok && close(h.corner_normal, h.face->normal(), 1e-3f);
		}
		check(ok, "set_corner_normals: cube at 30deg gives flat (face) normals");
	}
	{ //cube with negative threshold: everything smooth, corners point along diagonals
		Halfedge_Mesh mesh = cube_mesh();
		mesh.set_corner_normals(-1.0f);
		bool ok = true;
		for (auto const &h : mesh.halfedges) {
			if (h.face->boundary) continue;
			ok = ok && close(h.corner_normal, h.vertex->position.unit(), 1e-3f);
		}
		check(ok, "set_corner_normals: cube at -1 gives smooth (vertex) normals");
	}
	{ //explicit sharp flag overrides smoothing even with negative threshold
		Halfedge_Mesh mesh = cube_mesh();
		for (auto &e : mesh.edges) e.sharp = true;
		mesh.set_corner_normals(-1.0f);
		bool ok = true;
		for (auto const &h : mesh.halfedges) {
			if (h.face->boundary) continue;
			ok = ok && close(h.corner_normal, h.face->normal(), 1e-3f);
		}
		check(ok, "set_corner_normals: sharp flags force flat normals");
	}
	{ //tent mesh: 45-degree ridge is smooth at 60deg threshold, sharp at 30deg
		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_faces({
			Vec3(-1,0,-1), Vec3(1,0,-1),
			Vec3(-1,0, 1), Vec3(1,0, 1),
			Vec3(-1,1, 0), Vec3(1,1, 0)
		}, {
			{0, 4, 5, 1}, //back slope
			{2, 3, 5, 4}, //front slope
		});
		mesh.set_corner_normals(60.0f);
		bool ok = true;
		for (auto const &h : mesh.halfedges) {
			if (h.face->boundary) continue;
			if (h.vertex->position.y == 1.0f) { //ridge corners are smoothed
				ok = ok && std::abs(h.corner_normal.x) < 1e-3f && h.corner_normal.y > 0.5f && h.corner_normal.z > 0.5f;
			}
		}
		check(ok, "set_corner_normals: 90deg ridge smoothed at 60deg threshold");
		mesh.set_corner_normals(30.0f);
		ok = true;
		for (auto const &h : mesh.halfedges) {
			if (h.face->boundary) continue;
			ok = ok && close(h.corner_normal, h.face->normal(), 1e-3f);
		}
		check(ok, "set_corner_normals: 90deg ridge flat at 30deg threshold");
	}
}

static void test_corner_uvs_per_face() {
	Halfedge_Mesh mesh = cube_mesh();
	mesh.set_corner_uvs_per_face();
	bool ok = true;
	for (auto const &f : mesh.faces) {
		if (f.boundary) {
			continue;
		}
		//each corner of a quad face must get a distinct uv:
		std::vector<Vec2> uvs;
		auto h = f.halfedge;
		do {
			uvs.emplace_back(h->corner_uv);
			h = h->next;
		} while (h != f.halfedge);
		for (size_t i = 0; i < uvs.size(); ++i) {
			for (size_t j = i + 1; j < uvs.size(); ++j) {
				ok = ok && (uvs[i] - uvs[j]).norm() > 1e-3f;
			}
		}
		//cube face spans 2 units in each axis of its tangent frame:
		for (auto const &uv : uvs) {
			ok = ok && std::abs(uv.x) <= 1.0f + 1e-3f && std::abs(uv.y) <= 1.0f + 1e-3f;
		}
	}
	check(ok, "set_corner_uvs_per_face: cube faces get distinct, face-local uvs");
}

int main() {
	test_flip_orientation();
	test_corner_normals();
	test_corner_uvs_per_face();
	if (failures) {
		printf("%d check(s) failed.\n", failures);
		return 1;
	}
	printf("all checks passed.\n");
	return 0;
}

